import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Collection;
import java.io.IOException;
import java.util.Queue;
import java.util.LinkedList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CGregAndFriends solver = new CGregAndFriends();
        solver.solve(1, in, out);
        out.close();
    }

    static class CGregAndFriends {
        long mod = 1000000007;
        long INF = (long) 1e18 + 1;
        PrintWriter out;
        InputReader in;
        long[][] nCr = new long[100][100];

        long f(long p, int a, int b, int c, int d) {
            p *= nCr[a][b];
            p %= mod;
            p *= nCr[c][d];
            p %= mod;
            return p;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            this.out = out;
            this.in = in;
            int n = ni();
            int K = ni();
            int cnt1 = 0, cnt2 = 0;
            int i = 0, j = 0, k = 0;
            for (i = 0; i < 100; i++) {
                for (j = 0; j <= i; j++) {
                    if (j == 0 || j == i)
                        nCr[i][j] = 1;
                    else
                        nCr[i][j] = (nCr[i - 1][j] + nCr[i - 1][j - 1]) % mod;
                }
            }
            for (i = 0; i < n; i++) {
                if (ni() == 50)
                    cnt1++;
                else
                    cnt2++;
            }
            long[][][] dist = new long[200][200][2];
            long[][][] dp = new long[200][200][2];
            for (i = 0; i < 200; i++) {
                for (j = 0; j < 200; j++)
                    Arrays.fill(dist[i][j], INF);
            }
            dist[0][0][0] = 0;
            dp[0][0][0] = 1;
            Queue<Tuple> pq = new LinkedList<Tuple>();
            pq.add(new Tuple(0, 0, 0, 0));
            while (pq.size() > 0) {
                Tuple curr = pq.poll();
                int x = curr.x;
                int y = curr.y;
                int z = curr.z;
                long d = dist[x][y][z];
                if (z == 0) {
                    int rem_x = cnt1 - x;
                    int rem_y = cnt2 - y;
                    for (i = 0; i <= rem_x; i++) {
                        for (j = 0; j <= rem_y; j++) {
                            if (i + j == 0)
                                continue;
                            if (i * 50 + j * 100 > K)
                                break;
                            if (dist[i + x][j + y][z ^ 1] >= d + 1) {
                                if (dist[i + x][j + y][z ^ 1] > d + 1) {
                                    dist[i + x][j + y][z ^ 1] = d + 1;
                                    pq.add(new Tuple(dist[i + x][j + y][z ^ 1], i + x, j + y, z ^ 1));
                                    dp[i + x][j + y][z ^ 1] += f(dp[x][y][z], rem_x, i, rem_y, j);
                                    dp[i + x][j + y][z ^ 1] %= mod;
                                } else {
                                    dp[i + x][j + y][z ^ 1] += f(dp[x][y][z], rem_x, i, rem_y, j);
                                    dp[i + x][j + y][z ^ 1] %= mod;
                                }
                            }
                        }
                    }
                } else {
                    int rem_x = x;
                    int rem_y = y;
                    for (i = 0; i <= rem_x; i++) {
                        for (j = 0; j <= rem_y; j++) {
                            if (i + j == 0)
                                continue;
                            if (i * 50 + j * 100 > K)
                                break;
                            if (dist[x - i][y - j][z ^ 1] >= d + 1) {
                                if (dist[x - i][y - j][z ^ 1] > d + 1) {
                                    dist[x - i][y - j][z ^ 1] = d + 1;
                                    pq.add(new Tuple(dist[x - i][y - j][z ^ 1], x - i, y - j, z ^ 1));
                                    dp[x - i][y - j][z ^ 1] += f(dp[x][y][z], rem_x, i, rem_y, j);
                                    dp[x - i][y - j][z ^ 1] %= mod;
                                } else {
                                    dp[x - i][y - j][z ^ 1] += f(dp[x][y][z], rem_x, i, rem_y, j);
                                    dp[x - i][y - j][z ^ 1] %= mod;
                                }
                            }
                        }
                    }
                }
            }
            if (dist[cnt1][cnt2][1] == INF)
                pn(-1);
            else
                pn(dist[cnt1][cnt2][1]);
            pn(dp[cnt1][cnt2][1]);
        }

        int ni() {
            return in.nextInt();
        }

        void pn(long zx) {
            out.println(zx);
        }

        class Tuple {
            long d;
            int x;
            int y;
            int z;

            Tuple(long d, int x, int y, int z) {
                this.d = d;
                this.x = x;
                this.y = y;
                this.z = z;
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new UnknownError();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}


